import { LineChart, Line, XAxis, YAxis, Tooltip, Brush, Legend, ResponsiveContainer } from 'recharts';

const COLORS = ['#8884d8', '#82ca9d', '#ffc658', '#ff7c43'];

export function AdvancedChart({ data, sources, metric }: Props) {
  return (
    <ResponsiveContainer width="100%" height={300}>
