function CustomTooltip({ active, payload, label }: any) {
  if (!active || !payload) return null;
  return (
    <div className="bg-gray-800 shadow-lg rounded p-3 border border-gray-700">
      <p className="text-sm text-gray-500">{format(new Date(label), 'PPp')}</p>
      {payload.map((entry: any) => (
        <p key={entry.name} style={{ color: entry.color }}>
          {entry.name}: {entry.value.toFixed(2)}
        </p>
      ))}
    </div>
  );
}

// services/anomaly/zscore.ts
export function detectAnomaliesZScore(
  data: MetricPoint[],
  windowSize = 288, // 24h of 5-min intervals
  threshold = 3
): AnomalyResult[] {
  const anomalies: AnomalyResult[] = [];

  for (let i = windowSize; i < data.length; i++) {
    const window = data.slice(i - windowSize, i);
    const values = window.map(d => d.value);

    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    const std = Math.sqrt(
      values.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / values.length
    );

    if (std === 0) continue; // Constant values

    const zScore = (data[i].value - mean) / std;

    if (Math.abs(zScore) > threshold) {
      anomalies.push({
        timestamp: data[i].timestamp,
        value: data[i].value,
        expected: mean,
        zScore,
        severity: Math.abs(zScore) > 5 ? 'critical' : 'warning',
        type: zScore > 0 ? 'spike' : 'drop',
      });
    }
  }

  return anomalies;
}

