// utils/export.ts
import Papa from 'papaparse';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

export function exportCSV(data: any[], filename: string) {
  const csv = Papa.unparse(data);
  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${filename}_${format(new Date(), 'yyyy-MM-dd')}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

export async function exportPDF(elementId: string, title: string) {
  const element = document.getElementById(elementId);
  if (!element) return;

  const canvas = await html2canvas(element, { scale: 2 });
  const pdf = new jsPDF('landscape', 'mm', 'a4');

  pdf.setFontSize(18);
  pdf.text(title, 15, 15);
  pdf.setFontSize(10);
  pdf.text(`Generated: ${format(new Date(), 'PPp')}`, 15, 22);

  const imgWidth = 267; // A4 landscape width - margins
  const imgHeight = (canvas.height * imgWidth) / canvas.width;
  pdf.addImage(canvas.toDataURL('image/png'), 'PNG', 15, 30, imgWidth, imgHeight);

  pdf.save(`${title}_${format(new Date(), 'yyyy-MM-dd')}.pdf`);
}

// components/Heatmap.tsx
import { Fragment } from 'react';

export function Heatmap({ data }: { data: HeatmapCell[][] }) {
  const getColor = (value: number, max: number) => {
    const intensity = value / max;
    if (intensity > 0.8) return 'bg-red-500';
    if (intensity > 0.6) return 'bg-orange-400';
    if (intensity > 0.4) return 'bg-yellow-300';
    if (intensity > 0.2) return 'bg-green-300';
    return 'bg-green-100';
  };

  const days = ['Pzt', 'Sal', 'Çar', 'Per', 'Cum', 'Cmt', 'Paz'];

  return (
    <div className="bg-gray-800 rounded-lg p-4">
      <h3 className="font-medium text-gray-300 mb-4">İş Yükü Heatmap</h3>
      <div className="grid gap-1" style={{ gridTemplateColumns: 'auto repeat(24, 1fr)' }}>
        <div /> {/* Empty corner */}
        {Array.from({length: 24}, (_, h) => (
          <div key={h} className="text-xs text-gray-400 text-center">{h}</div>
        ))}
        {days.map((day, d) => (
          <Fragment key={d}>
            <div className="text-xs text-gray-500 flex items-center">{day}</div>
            {data[d]?.map((cell, h) => (
              <div
                key={`${d}-${h}`}
                className={`w-4 h-4 rounded-sm ${getColor(cell.value, cell.max)} cursor-pointer`}
                title={`${day} ${h}:00 - ${cell.value.toFixed(1)}`}
              />
            ))}
          </Fragment>
        ))}
      </div>
    </div>
  );
}

// components/LazyChart.tsx
import { useRef, useState, useEffect, memo } from 'react';

export const LazyChart = memo(function LazyChart({ children }: { children: React.ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: '100px' } // Start loading 100px before visible
    );

    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, []);

  return (
    <div ref={ref} style={{ minHeight: 300 }}>
      {visible ? children : <div className="animate-pulse bg-gray-200 h-full rounded" />}
    </div>
  );
});
